-- flock_pending_parent_split; executed query ID 01c7b539-0003-03ac-0003-b706001251fa
SELECT
            CASE WHEN NULLIF(NULLIF(LOWER(TRIM(TO_VARCHAR(c.CORRECTED_DATA:FLOCK_ID))),'none'),'null') IS NULL
                 THEN 'Missing Flock reference' ELSE 'Flock reference exists in source but is pending' END REASON_GROUP,
            COUNT(*) ROW_COUNT FROM EFNS_DEV.RAW.MIGRATION_CORRECTION_ROW c
            WHERE ORIGINAL_MIGRATION_BATCH_ID='DEV_MIGRATION_255ef9b50a52e766a7dff9' AND SOURCE_ENTITY='FLOCK_TRANSACTION'
            AND DISPOSITION='PENDING_CONFIRMATION' GROUP BY 1;

-- raw_source_counts; executed query ID 01c7b539-0003-02c7-0003-b706001288d6
SELECT SOURCE_FILENAME,SOURCE_ENTITY,COUNT(*) SOURCE_ROWS,COUNT_IF(VALIDATION_STATUS='READY') READY_ROWS,COUNT_IF(VALIDATION_STATUS='REJECTED') REJECTED_ROWS FROM EFNS_DEV.RAW.MIGRATION_RAW_ROW WHERE MIGRATION_BATCH_ID='DEV_MIGRATION_255ef9b50a52e766a7dff9' GROUP BY 1,2 ORDER BY 1;

-- production_reference_PRODUCER_ACCOUNT_ID; executed query ID 01c7b539-0003-03ac-0003-b706001251fe
SELECT COUNT(*) ROW_COUNT,COUNT(pr.PRODUCER_ACCOUNT_ID) NON_NULL,
                COUNT(CASE WHEN pr.PRODUCER_ACCOUNT_ID IS NOT NULL AND EXISTS (SELECT 1 FROM EFNS_DEV.CORE.ACCOUNT p WHERE p.ACCOUNT_ID=pr.PRODUCER_ACCOUNT_ID) THEN 1 END) MATCHED,
                COUNT(CASE WHEN pr.PRODUCER_ACCOUNT_ID IS NOT NULL AND NOT EXISTS (SELECT 1 FROM EFNS_DEV.CORE.ACCOUNT p WHERE p.ACCOUNT_ID=pr.PRODUCER_ACCOUNT_ID) THEN 1 END) ORPHANS
                FROM EFNS_DEV.CORE.PRODUCTION_RECORD pr;

-- production_reference_GRADER_ACCOUNT_ID; executed query ID 01c7b539-0003-02c7-0003-b706001288da
SELECT COUNT(*) ROW_COUNT,COUNT(pr.GRADER_ACCOUNT_ID) NON_NULL,
                COUNT(CASE WHEN pr.GRADER_ACCOUNT_ID IS NOT NULL AND EXISTS (SELECT 1 FROM EFNS_DEV.CORE.ACCOUNT p WHERE p.ACCOUNT_ID=pr.GRADER_ACCOUNT_ID) THEN 1 END) MATCHED,
                COUNT(CASE WHEN pr.GRADER_ACCOUNT_ID IS NOT NULL AND NOT EXISTS (SELECT 1 FROM EFNS_DEV.CORE.ACCOUNT p WHERE p.ACCOUNT_ID=pr.GRADER_ACCOUNT_ID) THEN 1 END) ORPHANS
                FROM EFNS_DEV.CORE.PRODUCTION_RECORD pr;

-- production_reference_FACILITY_ID; executed query ID 01c7b539-0003-03ac-0003-b70600125202
SELECT COUNT(*) ROW_COUNT,COUNT(pr.FACILITY_ID) NON_NULL,
                COUNT(CASE WHEN pr.FACILITY_ID IS NOT NULL AND EXISTS (SELECT 1 FROM EFNS_DEV.CORE.FACILITY p WHERE p.FACILITY_ID=pr.FACILITY_ID) THEN 1 END) MATCHED,
                COUNT(CASE WHEN pr.FACILITY_ID IS NOT NULL AND NOT EXISTS (SELECT 1 FROM EFNS_DEV.CORE.FACILITY p WHERE p.FACILITY_ID=pr.FACILITY_ID) THEN 1 END) ORPHANS
                FROM EFNS_DEV.CORE.PRODUCTION_RECORD pr;

-- production_reference_FLOCK_ID; executed query ID 01c7b539-0003-02c7-0003-b706001288de
SELECT COUNT(*) ROW_COUNT,COUNT(pr.FLOCK_ID) NON_NULL,
                COUNT(CASE WHEN pr.FLOCK_ID IS NOT NULL AND EXISTS (SELECT 1 FROM EFNS_DEV.CORE.FLOCK p WHERE p.FLOCK_ID=pr.FLOCK_ID) THEN 1 END) MATCHED,
                COUNT(CASE WHEN pr.FLOCK_ID IS NOT NULL AND NOT EXISTS (SELECT 1 FROM EFNS_DEV.CORE.FLOCK p WHERE p.FLOCK_ID=pr.FLOCK_ID) THEN 1 END) ORPHANS
                FROM EFNS_DEV.CORE.PRODUCTION_RECORD pr;

-- production_reference_IMPORT_ID; executed query ID 01c7b539-0003-03ac-0003-b70600125206
SELECT COUNT(*) ROW_COUNT,COUNT(pr.IMPORT_ID) NON_NULL,
                COUNT(CASE WHEN pr.IMPORT_ID IS NOT NULL AND EXISTS (SELECT 1 FROM EFNS_DEV.RAW.IMPORT_BATCH p WHERE p.IMPORT_ID=pr.IMPORT_ID) THEN 1 END) MATCHED,
                COUNT(CASE WHEN pr.IMPORT_ID IS NOT NULL AND NOT EXISTS (SELECT 1 FROM EFNS_DEV.RAW.IMPORT_BATCH p WHERE p.IMPORT_ID=pr.IMPORT_ID) THEN 1 END) ORPHANS
                FROM EFNS_DEV.CORE.PRODUCTION_RECORD pr;

-- production_provenance; executed query ID 01c7b539-0003-02c7-0003-b706001288e2
SELECT pr.SOURCE_TYPE,CASE WHEN m.TARGET_ID IS NOT NULL THEN 'Original Jensen batch lineage' ELSE 'Other / not original batch lineage' END PROVENANCE,
            COUNT(*) ROW_COUNT,COUNT(pr.PRODUCER_ACCOUNT_ID) PRODUCER_LINKS,COUNT(pr.GRADER_ACCOUNT_ID) GRADER_LINKS,
            COUNT(pr.FACILITY_ID) FACILITY_LINKS,COUNT(pr.FLOCK_ID) FLOCK_LINKS,COUNT(pr.MATCH_CONFIRMED_AT) CONFIRMED_TIMESTAMPS
            FROM EFNS_DEV.CORE.PRODUCTION_RECORD pr LEFT JOIN (SELECT DISTINCT TARGET_ID FROM EFNS_DEV.RAW.MIGRATION_ID_MAP WHERE MIGRATION_BATCH_ID='DEV_MIGRATION_255ef9b50a52e766a7dff9' AND SOURCE_ENTITY='PRODUCTION_RECORD') m
            ON m.TARGET_ID=pr.PRODUCTION_ID GROUP BY 1,2 ORDER BY 1,2;

-- production_raw_link_evidence; executed query ID 01c7b539-0003-03ac-0003-b7060012520a
SELECT COUNT(*) SOURCE_ROWS,
            COUNT(NULLIF(NULLIF(LOWER(TRIM(TO_VARCHAR(RAW_DATA:NEW_ACCOUNT))),'null'),'')) SOURCE_ACCOUNT,
            COUNT(NULLIF(NULLIF(LOWER(TRIM(TO_VARCHAR(RAW_DATA:NEW_GRADINGSTATION))),'null'),'')) SOURCE_GRADER,
            COUNT(NORMALIZED_DATA:FACILITY_ID::VARCHAR) NORMALIZED_FACILITY,
            COUNT(NORMALIZED_DATA:FLOCK_ID::VARCHAR) NORMALIZED_FLOCK
            FROM EFNS_DEV.RAW.MIGRATION_RAW_ROW WHERE MIGRATION_BATCH_ID='DEV_MIGRATION_255ef9b50a52e766a7dff9' AND SOURCE_ENTITY='PRODUCTION_RECORD';

-- production_link_origin_detail; executed query ID 01c7b539-0003-02c7-0003-b706001288e6
SELECT SOURCE_TYPE,
            COUNT(CASE WHEN FACILITY_ID LIKE 'DEV_MIGRATION_%%' THEN 1 END) DEV_PREFIX_FACILITY,
            COUNT(CASE WHEN FLOCK_ID LIKE 'DEV_MIGRATION_%%' THEN 1 END) DEV_PREFIX_FLOCK,
            COUNT(CASE WHEN FACILITY_ID IS NOT NULL AND FACILITY_ID NOT LIKE 'DEV_MIGRATION_%%' THEN 1 END) OTHER_FACILITY
            FROM EFNS_DEV.CORE.PRODUCTION_RECORD GROUP BY 1;

-- source_total_1999_21; executed query ID 01c7b539-0003-02c7-0003-b706001288ea
SELECT PRODUCER_ACCOUNT_ID,COUNT(*) RECORDS,COUNT(TOTAL) KNOWN,SUM(TOTAL) SOURCE_TOTAL FROM EFNS_DEV.CORE.PRODUCTION_RECORD WHERE REPORTING_YEAR=1999 AND REPORTING_WEEK=21 GROUP BY 1 ORDER BY 1;

-- source_total_2017_15; executed query ID 01c7b539-0003-02c7-0003-b706001288ee
SELECT PRODUCER_ACCOUNT_ID,COUNT(*) RECORDS,COUNT(TOTAL) KNOWN,SUM(TOTAL) SOURCE_TOTAL FROM EFNS_DEV.CORE.PRODUCTION_RECORD WHERE REPORTING_YEAR=2017 AND REPORTING_WEEK=15 GROUP BY 1 ORDER BY 1;

-- facility_source_and_conflict; executed query ID 01c7b539-0003-03ac-0003-b7060012520e
SELECT COUNT(*) PRODUCTION_ROWS,
            COUNT(CASE WHEN pr.FACILITY_ID IS NOT NULL THEN 1 END) DIRECT,
            COUNT(CASE WHEN pr.FACILITY_ID IS NULL AND fl.FACILITY_ID IS NOT NULL THEN 1 END) FLOCK_FALLBACK,
            COUNT(CASE WHEN pr.FACILITY_ID IS NULL AND fl.FACILITY_ID IS NULL THEN 1 END) NO_AVAILABLE,
            COUNT(CASE WHEN pr.FACILITY_ID IS NOT NULL AND fl.FACILITY_ID IS NOT NULL AND pr.FACILITY_ID<>fl.FACILITY_ID THEN 1 END) CONFLICT
            FROM EFNS_DEV.CORE.PRODUCTION_RECORD pr LEFT JOIN EFNS_DEV.CORE.FLOCK fl ON fl.FLOCK_ID=pr.FLOCK_ID;

